```
button("getJoke", "Get a joke!");
textLabel("setup", "");
textLabel("punchline", "");

onEvent("getJoke", "click", function() {
  startWebRequest("https://official-joke-api.appspot.com/random_joke", function(status, type, content) {
    if (status == 200) {
      var joke = JSON.parse(content);
      setText("setup", joke.setup);
      setText("punchline", joke.punchline);
    }
  });
});
```

